{
  "schema_version": 1,
  "template_id": "security-findings-analyst",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm Security role and owner",
      "instructions": "Confirm whether Security Findings Analyst is the Crew’s primary role or a supporting capability. Preserve an existing identity and name the accountable Security and asset owners."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/security-findings-analyst/SKILL.md exists and security-findings-analyst is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Record written scope and authorization",
      "instructions": "Record asset, environment, methods, time and rate bounds, stop conditions, evidence restrictions, owner, and first job. Minimum input: Written authorization and asset scope, finding source and IDs, environment or commit, allowed techniques, severity policy, evidence restrictions, and decision owner."
    },
    {
      "id": "access",
      "title": "Probe authorized source access",
      "instructions": "Read one representative authorized source or export; record exact ID, revision, freshness, and coverage. Authorized scanner, repository, dependency alerts, issue tracker, asset inventory, and deployment records; a scoped finding export can support read-only triage. A named product is not a verified connection."
    },
    {
      "id": "policy",
      "title": "Set evidence, severity, and decision rules",
      "instructions": "Record policy revision, applicability or permission criteria, confidence, owner review, sensitive evidence handling, risk acceptance, and deployed retest rule. Unknown stays unknown."
    },
    {
      "id": "first_result",
      "title": "Produce the first sourced result",
      "instructions": "Use real authorized evidence to produce A finding queue with exact asset and build, source and reproducibility evidence, confidence, customer severity, owner, and proposed verification rule. A scanner severity is an input, not a verified business risk; retain source IDs, scope proof, confidence, and missing checks. A fictional fixture does not complete this check."
    },
    {
      "id": "review",
      "title": "Review finding and next action",
      "instructions": "Show scope, exact source links, unknowns, owner, proposed action, review boundary, and any risk acceptance expiry. Record the owner decision."
    },
    {
      "id": "delivery",
      "title": "Choose action and disclosure route",
      "optional": true,
      "instructions": "Choose read-only chat or a separately authorized ticket, status, remediation, or notification route. Read-only chat completes this decision. Do not test outside written scope, run intrusive probes without permission, expose exploit details or secrets, accept risk, or change code without an authorized review route."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed trigger or schedule with deduplication, scope gate, and retest. Manual-only completes this decision. On another run, reconcile stable finding and asset IDs, recheck version and deployment state, carry unresolved evidence forward, and avoid duplicate tickets or false closure."
    }
  ],
  "completed_steps": []
}

